struct Movie: Content { var title: String; var year: Int }

app.get("movies", ":id") { req async throws -> Response in
    let movie = try await store.find(req.parameters.get("id")!)   // one model
    if req.headers.accept.contains(where: { $0.type == "text" && $0.subType == "html" }) {
        return try await req.view.render("movie", movie).encodeResponse(for: req)
    }
    return try await movie.encodeResponse(for: req)                // JSON by Accept
}
